def pdfs_wait_for_qa(apps, schema_editor):
    """A PDF a tutor attached before QA approved plans is put before QA; a Word
    copy is not a PDF, so the tutor uploads one (said 19 November 2026)."""
    TeachingPlan = apps.get_model('attendance', 'TeachingPlan')
    for plan in TeachingPlan.objects.exclude(document=''):
        if plan.document.name.lower().endswith('.pdf'):
            plan.document_status = 'pending'
            plan.document_uploaded_by_id = plan.created_by_id
            plan.document_uploaded_at = plan.updated_at
            plan.save(update_fields=['document_status', 'document_uploaded_by', 'document_uploaded_at'])


